using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]    // 5%: discount 249.95 -> 249
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]    // threshold belongs to upper band: 6%
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]
    [InlineData(LoyaltyTier.Platinum, 4_999, 4_550)]
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)]  // 10%
    [InlineData(LoyaltyTier.Green, 19_999, 18_800)]  // 6%: 1199.94 -> 1199
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]  // 8%
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]   // 10%
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // capped at 10%
    [InlineData(LoyaltyTier.Platinum, 10_001, 9_001)] // 10%: 1000.1 -> 1000
    [InlineData(LoyaltyTier.Green, 99, 95)]          // 4.95 -> 4
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier loyaltyTier, int subtotalCents, int expectedPayableCents)
    {
        var actual = new CalculatePayableTotal().For(subtotalCents, loyaltyTier);

        Assert.Equal(expectedPayableCents, actual);
    }
}
E
